Renderer::Renderer(SDL_Window* window,const std::filesystem::path& base,const Scene& scene):impl(std::make_unique<Impl>(window,base,scene)){impl->initialize();}
Renderer::~Renderer()=default;
bool Renderer::frame(const Camera& camera,bool cut){return impl->frame(camera,cut);}
void Renderer::rebuild(){impl->rebuildNeeded=true;}
bool Renderer::diagnostics()const{return impl->failed;}
